#!/usr/bin/env bash
# Keep build output from eating the disk.
#
#   scripts/prune-builds.sh              # prune now
#   scripts/prune-builds.sh --dry-run    # say what would go
#   scripts/prune-builds.sh --if-due     # at most every PRUNE_EVERY_HOURS (hooks)
#
# Everything removed is regenerated by the next build that needs it.
#
# Always removed (cheap or rarely needed):
#   - incremental-compilation caches
#   - cross-compiled targets
#   - the spikes' vendored, patched gpui-base
#
# Removed only when target/ is still over PRUNE_BUDGET_GB (20):
#   - everything else in it (`cargo clean`). The next build starts from
#     scratch, which takes a few minutes, so this is the last resort.
#
# Nothing is touched while a cargo or rustc process is running.
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
target="$root/target"
budget_gb="${PRUNE_BUDGET_GB:-20}"
every_hours="${PRUNE_EVERY_HOURS:-6}"
stamp="$target/.last-prune"

dry_run=false
if_due=false
for arg in "$@"; do
  case "$arg" in
    --dry-run) dry_run=true ;;
    --if-due) if_due=true ;;
    *) echo "usage: $0 [--dry-run] [--if-due]" >&2; exit 2 ;;
  esac
done

if $if_due && [ -f "$stamp" ] && [ -z "$(find "$stamp" -mmin +$((every_hours * 60)) 2>/dev/null)" ]; then
  exit 0
fi

if pgrep -x cargo >/dev/null 2>&1 || pgrep -x rustc >/dev/null 2>&1; then
  echo "prune-builds: a build is running; skipping" >&2
  exit 0
fi

size_kb() { du -sk "$1" 2>/dev/null | cut -f1 || echo 0; }
human() { awk -v k="$1" 'BEGIN { printf (k > 1048576 ? "%.1f GB" : "%.0f MB"), (k > 1048576 ? k / 1048576 : k / 1024) }'; }

freed=0
target_freed=0
remove() {
  local path="$1"
  [ -e "$path" ] || return 0
  local kb
  kb=$(size_kb "$path")
  if $dry_run; then
    echo "would remove $(human "$kb")  ${path#"$root"/}"
  else
    # Finder can recreate .DS_Store in a folder while it's being emptied,
    # which makes rm report "Directory not empty"; a retry wins the race.
    local tries=0
    until rm -rf "$path" 2>/dev/null || [ $((tries += 1)) -ge 3 ]; do sleep 1; done
    if [ -e "$path" ]; then
      echo "could not fully remove ${path#"$root"/}" >&2
    else
      echo "removed $(human "$kb")  ${path#"$root"/}"
    fi
  fi
  freed=$((freed + kb))
  case "$path" in "$target"/*) target_freed=$((target_freed + kb)) ;; esac
}

# Tier 1.
if [ -d "$target" ]; then
  # Cross targets first, so their incremental caches aren't counted twice.
  for triple in aarch64-apple-ios aarch64-apple-ios-sim x86_64-apple-ios \
                aarch64-linux-android armv7-linux-androideabi i686-linux-android x86_64-linux-android; do
    remove "$target/$triple"
  done
  for profile in "$target"/*/; do
    remove "${profile%/}/incremental"
  done
  remove "$target/spike-vendor"
fi

# Tier 2.
if [ -d "$target" ]; then
  left_kb=$(size_kb "$target")
  budget_kb=$((budget_gb * 1048576))
  if $dry_run; then
    left_kb=$((left_kb - target_freed > 0 ? left_kb - target_freed : 0))
  fi
  if [ "$left_kb" -gt "$budget_kb" ]; then
    echo "target is $(human "$left_kb"), over the ${budget_gb} GB budget"
    if $dry_run; then
      echo "would run cargo clean"
      freed=$((freed + left_kb))
    else
      (cd "$root" && cargo clean -q)
      echo "removed $(human "$left_kb")  target (cargo clean)"
      freed=$((freed + left_kb))
    fi
  fi
fi

if ! $dry_run; then
  mkdir -p "$target"
  touch "$stamp"
fi
echo "prune-builds: $($dry_run && echo would free || echo freed) $(human "$freed")"
